<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Redirect;
class AdminReturnController extends Controller
{
 public function index(Request $request){$query=DB::table('order_returns as r')->join('orders as o','o.id','=','r.order_id')->select('r.*','o.order_number');if($request->filled('status'))$query->where('r.status',$request->status);if($request->filled('search')){$term=$request->search;$query->where(function($q)use($term){$q->where('r.return_number','like','%'.$term.'%')->orWhere('o.order_number','like','%'.$term.'%')->orWhere('r.customer_name','like','%'.$term.'%');});}$returns=$query->latest('r.id')->paginate(25)->appends($request->query());return view('admin.admin-pages.returns',compact('returns'));}
 public function show($id){$return=DB::table('order_returns as r')->join('orders as o','o.id','=','r.order_id')->where('r.id',$id)->select('r.*','o.order_number','o.payment_method','o.total as order_total')->first();abort_unless($return,404);$items=DB::table('order_return_items')->where('order_return_id',$id)->get();$refund=DB::table('refunds')->where('order_return_id',$id)->first();$creditNote=DB::table('credit_notes')->where('order_return_id',$id)->first();return view('admin.admin-pages.return-details',compact('return','items','refund','creditNote'));}
 public function update(Request $request,$id){$this->validate($request,['action'=>'required|in:approve,reject,receive,refund','admin_note'=>'nullable|max:3000']);try{DB::transaction(function()use($request,$id){$return=DB::table('order_returns')->where('id',$id)->lockForUpdate()->first();abort_unless($return,404);if($request->action==='approve'){$this->requireStatus($return,['requested']);$amount=min((float)$return->requested_amount,max(0,(float)$request->input('approved_amount',$return->requested_amount)));if($amount<=0)throw new \RuntimeException('Approved refund amount must be greater than zero.');DB::table('order_returns')->where('id',$id)->update(['status'=>'approved','approved_amount'=>$amount,'admin_note'=>$request->admin_note,'processed_by'=>session('admin_name'),'approved_at'=>now(),'updated_at'=>now()]);return;}if($request->action==='reject'){$this->requireStatus($return,['requested']);DB::table('order_returns')->where('id',$id)->update(['status'=>'rejected','admin_note'=>$request->admin_note,'processed_by'=>session('admin_name'),'completed_at'=>now(),'updated_at'=>now()]);return;}if($request->action==='receive'){$this->requireStatus($return,['approved']);$location=DB::table('inventory_locations')->where('is_default',1)->where('is_active',1)->first();if(!$location)throw new \RuntimeException('No active default warehouse is configured.');$items=DB::table('order_return_items')->where('order_return_id',$id)->lockForUpdate()->get();foreach($items as $item){$restock=$request->input('restock.'.$item->id)==='1';DB::table('order_return_items')->where('id',$item->id)->update(['restock'=>$restock?1:0,'updated_at'=>now()]);if(!$restock||$item->inventory_restored_at||!$item->product_id)continue;$balance=DB::table('product_location_stock')->where('location_id',$location->id)->where('product_id',$item->product_id)->lockForUpdate()->first();if($balance)DB::table('product_location_stock')->where('id',$balance->id)->increment('quantity',$item->quantity);else DB::table('product_location_stock')->insert(['location_id'=>$location->id,'product_id'=>$item->product_id,'quantity'=>$item->quantity,'created_at'=>now(),'updated_at'=>now()]);$total=(int)DB::table('product_location_stock')->where('product_id',$item->product_id)->sum('quantity');DB::table('product')->where('id',$item->product_id)->update(['stock_quantity'=>$total,'product_condition'=>$total>0?'In Stock':'Out Of Stock','updated_at'=>now()]);DB::table('order_return_items')->where('id',$item->id)->update(['inventory_restored_at'=>now(),'updated_at'=>now()]);}DB::table('order_returns')->where('id',$id)->update(['status'=>'received','admin_note'=>$request->admin_note?:$return->admin_note,'processed_by'=>session('admin_name'),'received_at'=>now(),'updated_at'=>now()]);return;}$this->requireStatus($return,['received']);$amount=(float)$return->approved_amount;if($amount<=0)throw new \RuntimeException('This return has no approved refund amount.');$refundId=DB::table('refunds')->insertGetId(['refund_number'=>'RFD-'.date('ymd').'-'.strtoupper(str_random(6)),'order_return_id'=>$id,'order_id'=>$return->order_id,'amount'=>$amount,'method'=>$request->input('refund_method','original_payment'),'transaction_reference'=>$request->transaction_reference,'status'=>'completed','note'=>$request->admin_note,'processed_by'=>session('admin_name'),'refunded_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('credit_notes')->insert(['credit_note_number'=>'CN-'.date('ymd').'-'.strtoupper(str_random(6)),'order_return_id'=>$id,'refund_id'=>$refundId,'order_id'=>$return->order_id,'amount'=>$amount,'issued_at'=>now(),'issued_by'=>session('admin_name'),'created_at'=>now(),'updated_at'=>now()]);DB::table('order_returns')->where('id',$id)->update(['status'=>'refunded','admin_note'=>$request->admin_note?:$return->admin_note,'processed_by'=>session('admin_name'),'completed_at'=>now(),'updated_at'=>now()]);});}catch(\RuntimeException $e){return Redirect::back()->withInput()->with('exception',$e->getMessage());}return Redirect::back()->with('message','Return workflow updated successfully.');}
 public function creditNote(Request $request,$id){$note=DB::table('credit_notes as c')->join('order_returns as r','r.id','=','c.order_return_id')->join('orders as o','o.id','=','c.order_id')->where('c.id',$id)->select('c.*','r.return_number','r.customer_name','r.email','r.phone','o.order_number','o.user_id')->first();abort_unless($note,404);$allowed=$request->session()->has('admin_id')||(auth()->check()&&(int)$note->user_id===(int)auth()->id());abort_unless($allowed,403);$items=DB::table('order_return_items')->where('order_return_id',$note->order_return_id)->get();return view('front-end.pages.credit-note',compact('note','items'));}
 private function requireStatus($return,array $statuses){if(!in_array($return->status,$statuses,true))throw new \RuntimeException('This action is not valid for the current return status.');}
}
